-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := '1ad74fd3-6a25-452c-a4b1-668f8e3be8e6';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
  v_m3 uuid;
begin
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where course_id = v_course_id;

  insert into public.levels (course_id, title, description, order_number) values
    (v_course_id, 'HTML', 'The language that holds every web page together — structure, text, links, media, forms, and semantic markup that describes what your content actually means.', 2)
  returning id into v_level;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'HTML Structure & Text', 'The skeleton every web page is built from — the boilerplate, headings, paragraphs, lists, attributes, and why the tag you choose carries meaning, not just appearance.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Your First HTML Page', 'Write the HTML boilerplate every page starts with — doctype, html, head, body — and open your own page in a browser.', 'https://www.youtube.com/watch?v=07EVpWb8dtg', 1,
      array['Write a valid HTML boilerplate from memory', 'Explain what doctype, head, and body each do', 'Open a local .html file in a browser and see your changes'],
      'Every HTML page starts with the same handful of lines. `<!DOCTYPE html>` tells the browser to use modern standards. `<html>` wraps everything. `<head>` holds information *about* the page — its title, character encoding, links to stylesheets — none of which appears on screen. `<body>` holds everything the visitor actually sees. Get into the habit of typing this by hand a few times rather than copying it; it''s short, and knowing it cold means you can start any page from nothing.',
      'Create a file called `index.html`, type the full boilerplate by hand (no copy-paste), put your name in an `<h1>` inside the body, and open it in your browser.',
      '[{"question":"What goes inside the <head> element?","options":["Everything the visitor sees on the page","Information about the page — title, encoding, stylesheet links","Only images","The page footer"],"correct_index":1},{"question":"What does <!DOCTYPE html> do?","options":["Adds a heading","Tells the browser to render using modern HTML standards","Imports CSS","Creates a link"],"correct_index":1}]'::jsonb),
    (v_m1, 'Adding Content: Text and Paragraphs', 'Put real content on the page with paragraphs, and see how the browser treats whitespace differently from how you typed it.', 'https://www.youtube.com/watch?v=sbvQVPvjUdk', 2,
      array['Add paragraphs of text with the <p> element', 'Explain why extra spaces and line breaks in your code collapse in the browser', 'Build up a page with several blocks of real content'],
      'The `<p>` element marks a paragraph, and it''s the workhorse of body text. One thing surprises everyone at first: HTML collapses whitespace. If you press Enter five times or add twenty spaces, the browser still renders a single space. Line breaks and spacing on the page come from the elements you choose and, later, from CSS — never from hitting Enter in your editor. That separation is deliberate: your HTML describes *what* the content is, and CSS decides how it''s spaced.',
      'Write three paragraphs about anything, deliberately adding lots of extra blank lines and spaces between words in your code, then reload the browser and observe how they collapse.',
      '[{"question":"What happens to extra spaces and line breaks in HTML?","options":["They display exactly as typed","The browser collapses them into a single space","They cause an error","They create new paragraphs"],"correct_index":1},{"question":"Which element marks a paragraph of text?","options":["<para>","<p>","<text>","<body>"],"correct_index":1}]'::jsonb),
    (v_m1, 'Headings and Hierarchy', 'Use h1 through h6 to give a page a real outline — and understand why skipping heading levels breaks things for search engines and screen readers.', 'https://www.youtube.com/watch?v=iSFXFG4CMUU', 3,
      array['Use h1-h6 to structure a document', 'Explain why heading order matters and shouldn''t be skipped', 'Choose heading levels based on meaning rather than text size'],
      'Headings run from `<h1>` (most important) down to `<h6>`, and together they form an outline of your page. The rule that trips people up: don''t pick a heading level because of how big it looks — pick it because of where the section sits in the hierarchy, then adjust size with CSS later. Skipping from `<h1>` straight to `<h4>` because h4 looked right visually breaks that outline, which matters directly for the screen-reader users and search engines that navigate a page by its headings.',
      'Outline a page about a topic you know — one h1, two or three h2 sections, and an h3 under one of them. Check the order reads as a sensible table of contents.',
      '[{"question":"How many heading levels does HTML provide?","options":["Three","Six","Ten","Unlimited"],"correct_index":1},{"question":"Why shouldn''t you choose a heading level based on its size?","options":["Sizes are random","Headings define the page''s outline for screen readers and search engines — size is CSS''s job","Bigger headings load slower","You should always use h1"],"correct_index":1}]'::jsonb),
    (v_m1, 'Lists: Ordered, Unordered, and Nested', 'Build bulleted and numbered lists, and nest one inside another for sub-points.', 'https://www.youtube.com/watch?v=m61h9YEB1fw', 4,
      array['Build unordered (<ul>) and ordered (<ol>) lists', 'Explain when order is meaningful and which list to use', 'Nest a list inside another list item'],
      '`<ul>` makes a bulleted list where order doesn''t matter; `<ol>` makes a numbered list where it does — recipe steps, rankings, instructions. Both hold `<li>` items. Choose based on meaning, not appearance: if reordering the items would change what they mean, use `<ol>`. Lists also nest — a `<ul>` placed *inside* an `<li>` creates sub-points, which is exactly how multi-level navigation menus are structured.',
      'Build a nested list: an ordered list of three steps, where step two contains an unordered list of two sub-points.',
      '[{"question":"When should you use <ol> instead of <ul>?","options":["When you want bullets","When the order of items actually matters","When the list is long","They''re interchangeable"],"correct_index":1},{"question":"Where does a nested list go?","options":["Directly inside the <ul>","Inside an <li> of the outer list","Before the list","In the <head>"],"correct_index":1}]'::jsonb),
    (v_m1, 'HTML Attributes', 'Attributes are the extra information you attach to a tag — href, src, alt, class. Learn how they''re written and why nearly every useful element needs them.', 'https://www.youtube.com/watch?v=UB1O30fR-EE', 5,
      array['Explain what an attribute is and where it goes in a tag', 'Write attributes with correct name="value" syntax', 'Identify common attributes: href, src, alt, class, id'],
      'An attribute lives inside a tag''s opening bracket and gives that element extra information: `<a href="...">` says where a link goes, `<img src="..." alt="...">` says which image to load and how to describe it. The syntax is always `name="value"`, with multiple attributes separated by spaces. Attributes are what make elements useful — a link without `href` goes nowhere, an image without `src` shows nothing. This is a broad crash course; attributes come up early and recur throughout, so treat it as a tour rather than a single narrow topic.',
      'Take a page you''ve already written and add at least three different attributes to it — an `id` on a heading, a `class` on a paragraph, and an `alt` on an image.',
      '[{"question":"Where is an attribute written?","options":["Inside the element''s opening tag","Between the opening and closing tags","In the <head>","In a separate file"],"correct_index":0},{"question":"What is the correct attribute syntax?","options":["name: value","name=\"value\"","name -> value","{name value}"],"correct_index":1}]'::jsonb),
    (v_m1, 'Semantic Meaning: Strong and Em', 'Why <strong> and <em> are not just bold and italic — and why choosing the meaningful tag matters for accessibility.', 'https://www.youtube.com/watch?v=bA1zt_wkDNE', 6,
      array['Distinguish <strong>/<em> from <b>/<i>', 'Explain what semantic markup means and who benefits from it', 'Choose the right element based on meaning rather than appearance'],
      '`<strong>` and `<em>` look like bold and italic, but they carry meaning: strong marks genuine importance, em marks genuine emphasis, and a screen reader can change its delivery accordingly. `<b>` and `<i>` are purely visual — bold and italic with no meaning attached. The practical rule: if you''re marking something as *important*, use `<strong>`; if you just want it visually bold for style reasons, that''s CSS''s job. This is your first encounter with semantic HTML, an idea that runs through the whole rest of this Learning Path — the tag you choose describes what the content *is*, not how it looks.',
      'Write a short warning paragraph. Mark the genuinely critical phrase with <strong>, then view it in a browser and note that the styling is identical to <b> — the difference is the meaning, not the appearance.',
      '[{"question":"What''s the difference between <strong> and <b>?","options":["No difference at all","<strong> conveys importance semantically; <b> is purely visual bold","<b> is newer","<strong> only works in headings"],"correct_index":1},{"question":"Who benefits most directly from semantic markup?","options":["Nobody, it''s cosmetic","Screen reader users and search engines","Only the developer","Only mobile users"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Links, Images & Media', 'Connect pages together and bring in images, video, and audio — plus the head-section tags that control how your page appears in browsers and search results.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Links and Anchor Tags', 'The element that makes the web a web — anchor tags, href, and opening links in a new tab.', 'https://www.youtube.com/watch?v=ZOI7Tq5Zq2s', 1,
      array['Create a link with <a> and href', 'Link to an external site and to another page in your own project', 'Use target="_blank" and know when it''s appropriate'],
      '`<a href="...">` is the anchor element, and it''s the single feature that turns isolated documents into the web. The `href` attribute holds the destination — a full URL for an external site, or a filename for a page in your own project. `target="_blank"` opens the link in a new tab, which is worth using sparingly: it''s reasonable for external sites so people don''t lose your page, but it takes control away from the user, so it shouldn''t be your default.',
      'Make two HTML pages and link them to each other, then add a third link out to an external website that opens in a new tab.',
      '[{"question":"Which attribute holds a link''s destination?","options":["src","href","link","url"],"correct_index":1},{"question":"What does target=\"_blank\" do?","options":["Removes the link styling","Opens the link in a new tab","Makes the link invisible","Downloads the page"],"correct_index":1}]'::jsonb),
    (v_m2, 'Relative vs Absolute File Paths', 'Why a link works on your machine but breaks once the site is live — the difference between relative and absolute paths.', 'https://www.youtube.com/watch?v=HAZzTG1EcKc', 2,
      array['Explain the difference between a relative and an absolute path', 'Navigate up and down folders with ../ and folder/', 'Diagnose a broken image or link caused by a wrong path'],
      'An absolute path is the full address (`https://example.com/images/logo.png`). A relative path is directions from the file you''re currently in: `images/logo.png` looks in an `images` folder alongside the current file, and `../images/logo.png` goes up one folder first. Relative paths are what you use inside your own project, because they keep working when the whole project moves to a server. Nearly every broken-image bug a beginner hits is a wrong relative path — being able to read one carefully saves hours.',
      'Create an `images` folder inside your project, put a picture in it, and link to it from a page one folder above using a relative path. Then deliberately break it with a wrong path and read the browser''s error.',
      '[{"question":"What does ../ mean in a file path?","options":["Go into a subfolder","Go up one folder level","Start from the website root","Repeat the current folder"],"correct_index":1},{"question":"Why use relative paths inside your own project?","options":["They''re shorter to type only","They keep working when the project is moved or deployed to a server","They load faster","They''re required by HTML"],"correct_index":1}]'::jsonb),
    (v_m2, 'Adding Images', 'Put images on the page with the img element — and write alt text that actually does its job.', 'https://www.youtube.com/watch?v=Hh_se2Zqsdk', 3,
      array['Add an image with <img>, src, and alt', 'Write alt text that describes the image''s purpose', 'Explain why <img> needs no closing tag'],
      '`<img src="..." alt="...">` places an image. `src` points at the file; `alt` describes it for anyone who can''t see it — screen reader users, and everyone when the image fails to load on a slow connection. Good alt text describes the image''s *purpose* in context, not just its contents: for a logo linking home, "SkillPath Africa home" beats "logo image". If an image is purely decorative, use `alt=""` so screen readers skip it rather than announcing a filename. `<img>` is a void element — there''s no `</img>`.',
      'Add three images to a page: a meaningful photo, a logo that links somewhere, and a purely decorative divider. Write appropriate alt text for each, including an empty alt for the decorative one.',
      '[{"question":"What should alt text describe?","options":["The file name","The image''s purpose in context, for people who can''t see it","The image''s dimensions","Nothing — it''s optional decoration"],"correct_index":1},{"question":"What alt value should a purely decorative image have?","options":["alt=\"decoration\"","alt=\"\" (empty)","No alt attribute at all","alt=\"image\""],"correct_index":1}]'::jsonb),
    (v_m2, 'Embedding Video', 'Add a video player to your page with the video element, and understand why multiple source formats exist.', 'https://www.youtube.com/watch?v=BAx2GaMW2qA', 4,
      array['Embed a video with the <video> element', 'Use the controls attribute and understand autoplay''s downsides', 'Explain why several <source> formats (mp4, webm, ogg) are offered'],
      '`<video>` embeds a player directly in the page — no plugin required, which was not always true of the web. Add `controls` so the visitor gets play, pause, and volume; without it there''s no way to start the video. Multiple `<source>` elements let the browser pick a format it supports, since not every browser handles every codec. Be very careful with `autoplay`: it burns mobile data without consent, which matters a lot for learners on limited bundles, and most browsers now block autoplay with sound anyway.',
      'Embed a short video file with controls enabled. Then remove the controls attribute, reload, and notice you can no longer play it.',
      '[{"question":"What does the controls attribute do on <video>?","options":["Nothing visible","Shows play, pause, and volume controls to the visitor","Compresses the video","Autoplays the video"],"correct_index":1},{"question":"Why provide multiple <source> formats?","options":["To make the file smaller","Different browsers support different video codecs","It''s required by HTML","To show multiple videos at once"],"correct_index":1}]'::jsonb),
    (v_m2, 'Embedding Audio', 'The audio element — adding music, podcasts, or sound clips to a page.', 'https://www.youtube.com/watch?v=uof_zYxtnp0', 5,
      array['Embed audio with the <audio> element', 'Apply the controls attribute so playback is usable', 'Recognise common audio formats used on the web'],
      '`<audio>` works almost identically to `<video>`: point it at a file, add `controls`, and optionally offer several `<source>` formats for browser compatibility. It''s the right element for podcast episodes, pronunciation clips, or background music the user chooses to start. The same autoplay caution applies, more strongly — audio starting unexpectedly is one of the most disliked things a web page can do, and it''s especially costly for someone on metered mobile data.',
      'Embed an audio file with controls, then add a second <source> in a different format and confirm the player still works.',
      '[{"question":"Which element embeds sound in a page?","options":["<sound>","<audio>","<music>","<media>"],"correct_index":1},{"question":"Why is autoplaying audio generally a bad idea?","options":["It''s not supported","It surprises users and consumes their data without consent","It slows the CPU","It breaks the layout"],"correct_index":1}]'::jsonb),
    (v_m2, 'The Head Section: Title, Charset, and Meta Tags', 'The invisible part of your page that controls the browser tab, character encoding, mobile scaling, and your search-result snippet.', 'https://www.youtube.com/watch?v=kUMe1FH4CHE', 6,
      array['Set the page <title> and explain where it appears', 'Explain what charset and the viewport meta tag do', 'Write a meta description and say where it''s used'],
      'Watch Chapter 2, "Head Element", of this full course. Nothing in `<head>` renders on the page, but it controls a lot: `<title>` sets the browser tab text and the clickable headline in search results; `<meta charset="UTF-8">` ensures accented characters and symbols display correctly instead of turning into gibberish; and the viewport meta tag is what makes responsive design work on phones at all — without it, mobile browsers pretend to be desktop-width and zoom out. The meta description doesn''t affect ranking directly but is often the snippet people read before deciding whether to click.',
      'Add a descriptive <title>, a UTF-8 charset, a viewport meta tag, and a meta description to one of your pages. Check the tab text changes, then view the page on a narrow window.',
      '[{"question":"Where does the <title> element''s text appear?","options":["At the top of the page body","In the browser tab and as the search-result headline","As a heading","Nowhere"],"correct_index":1},{"question":"What does the viewport meta tag do?","options":["Sets the page colour","Makes mobile browsers render at device width instead of faking desktop width","Loads CSS","Compresses images"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Forms & Semantic HTML', 'Collect input from real users, lay out tabular data properly, and structure a page with elements that describe what each region actually is — then check your markup is valid.', v_module_offset + 3)
  returning id into v_m3;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m3, 'Building Your First Form', 'The form element end to end — action, method, and what actually happens when someone hits submit.', 'https://www.youtube.com/watch?v=fNcJuPIZ2WE', 1,
      array['Build a working form with <form>, inputs, and a submit button', 'Explain what the action and method attributes control', 'Describe the difference between GET and POST for form submission'],
      'A `<form>` wraps the inputs you want submitted together. `action` says where the data goes; `method` says how — `GET` puts the values in the URL (fine for a search box, wrong for anything private), `POST` sends them in the request body (what you want for logins, sign-ups, or anything sensitive). A `<button type="submit">` triggers the send. Right now the data has nowhere to go, and that''s fine: Level 6 covers backends. Learning the front half properly first means you''ll understand exactly what the server is receiving when you get there.',
      'Build a contact form with a name field, an email field, a message box, and a submit button. Set method="POST" and observe what happens when you submit it.',
      '[{"question":"What does the method attribute control?","options":["The form''s appearance","How the data is sent — GET (in the URL) or POST (in the request body)","Which page loads next","The input types allowed"],"correct_index":1},{"question":"Why is GET a poor choice for a password field?","options":["It''s slower","The values appear in the URL, where they can be seen and logged","It doesn''t work with forms","It requires JavaScript"],"correct_index":1}]'::jsonb),
    (v_m3, 'Input Types and Attributes', 'The many input types — email, password, number, date, checkbox, radio, file — and the attributes that make them behave.', 'https://www.youtube.com/watch?v=zIN54lhJtQU', 2,
      array['Choose the right input type for a given piece of data', 'Use required, placeholder, and value attributes', 'Explain how input type improves the mobile keyboard and built-in validation'],
      '`type` on an `<input>` does far more than you''d expect. `type="email"` gives free browser validation and, crucially on phones, brings up a keyboard with an @ key; `type="number"` brings up a numeric pad; `type="date"` gives a real date picker. Choosing the right type is one of the cheapest usability wins available, and it matters most on mobile — which is most of your audience. `required` blocks submission when empty, and `placeholder` shows a hint (a hint, not a label — those are different, as the next lesson covers).',
      'Build a sign-up form using at least five different input types, including email, password, number, and a checkbox. Open it on a phone and notice the keyboard change between fields.',
      '[{"question":"What''s a practical benefit of type=\"email\" on mobile?","options":["It changes the colour","It shows a keyboard with an @ key and validates the format","It encrypts the value","It makes the field wider"],"correct_index":1},{"question":"What does the required attribute do?","options":["Marks the field with an asterisk automatically","Prevents form submission while the field is empty","Makes the field read-only","Saves the value"],"correct_index":1}]'::jsonb),
    (v_m3, 'Labels and Form Accessibility', 'Why every input needs a real label — and how fieldset and legend group related fields for screen reader users.', 'https://www.youtube.com/watch?v=frAGrGN00OA', 3,
      array['Associate a <label> with an input using for and id', 'Explain why a placeholder is not a substitute for a label', 'Group related inputs with <fieldset> and <legend>'],
      'A `<label for="email">` tied to `<input id="email">` does two things: it tells a screen reader what the field is, and it makes the label text clickable to focus the input — a real help on small touchscreens. Placeholders are not labels: they vanish the moment someone starts typing, leaving no indication of what the field was, and they''re poorly announced by assistive tech. `<fieldset>` with a `<legend>` groups related inputs, which is how a screen reader knows that five radio buttons all answer one question rather than being five unrelated choices.',
      'Take your sign-up form and add a properly associated label to every input. Then click each label and confirm it focuses the right field.',
      '[{"question":"How is a <label> associated with an input?","options":["By placing it nearby","The label''s for attribute matches the input''s id","Automatically by the browser","Using the name attribute"],"correct_index":1},{"question":"Why isn''t a placeholder a substitute for a label?","options":["It is a fine substitute","It disappears once typing starts and is poorly announced by screen readers","It''s too small","It only works on desktop"],"correct_index":1}]'::jsonb),
    (v_m3, 'Tables in HTML', 'Build a real data table with rows, cells, and headers — and know when a table is genuinely the right tool.', 'https://www.youtube.com/watch?v=ZEHRyN6y71M', 4,
      array['Build a table with <table>, <tr>, <td>, and <th>', 'Use <thead> and <tbody> to structure a table', 'Explain why tables should not be used for page layout'],
      'A table is for tabular data — anything with meaningful rows and columns, like a price list or a timetable. `<tr>` is a row, `<td>` a cell, `<th>` a header cell that tells assistive tech what a column or row contains. `<thead>` and `<tbody>` separate the header from the data. One historical warning worth knowing: in the early web, tables were widely abused to lay out entire pages. Don''t — CSS handles layout now (Level 3), and a layout table is confusing nonsense to a screen reader trying to read it as data.',
      'Build a table showing a weekly timetable, with days as column headers using <th> and a proper <thead> and <tbody>.',
      '[{"question":"What is <th> used for?","options":["A regular cell","A header cell describing a column or row","The table title","A table footer"],"correct_index":1},{"question":"Why shouldn''t tables be used for page layout?","options":["They''re deprecated entirely","CSS handles layout, and layout tables confuse screen readers reading them as data","They load slowly","They only work in old browsers"],"correct_index":1}]'::jsonb),
    (v_m3, 'Semantic HTML Elements', 'header, nav, main, article, section, footer — elements that describe what a region of the page IS, not just how it looks.', 'https://www.youtube.com/watch?v=kX3TfdUqpuU', 5,
      array['Use header, nav, main, article, section, and footer appropriately', 'Explain the difference between a <div> and a semantic element', 'Describe how semantic structure helps screen readers and search engines'],
      'A `<div>` is a generic box with no meaning. Semantic elements say what a region actually is: `<nav>` is navigation, `<main>` is the primary content, `<article>` is a self-contained piece, `<footer>` closes out a page or section. Visually they render identically to divs — the difference is entirely in meaning. That meaning is what lets a screen reader user jump straight to `<main>` and skip the navigation, and what helps search engines understand a page''s structure. The rule of thumb: reach for a semantic element first, and fall back to `<div>` only when nothing meaningful fits.',
      'Rebuild one of your existing pages using semantic elements throughout — header, nav, main, and footer — replacing generic divs wherever a meaningful element exists.',
      '[{"question":"How does <section> differ visually from <div>?","options":["It has a border by default","It doesn''t — the difference is meaning, not appearance","It''s always full width","It centres its content"],"correct_index":1},{"question":"What practical benefit does <main> give a screen reader user?","options":["None","They can jump straight to the primary content, skipping navigation","It reads the text louder","It translates the page"],"correct_index":1}]'::jsonb),
    (v_m3, 'Validating Your HTML', 'Catch broken markup before it causes mysterious bugs, using the official W3C validator.', 'https://www.youtube.com/watch?v=P0EGYTb1cBs', 6,
      array['Run a page through the W3C validator', 'Read a validator error and locate it in your code', 'Explain why invalid HTML can cause unpredictable rendering'],
      'Watch the "Validating your HTML code" chapter near the end of this video. Browsers try very hard to render broken HTML rather than showing an error, which sounds helpful but means an unclosed tag can silently produce a bizarre layout you''ll spend an hour chasing in CSS. The W3C validator at validator.w3.org checks your markup against the spec and points at the exact line. Running it whenever something looks inexplicably wrong is one of the fastest debugging habits you can build — and it''s a habit that carries directly into the debugging method from Level 1.',
      'Paste one of your pages into validator.w3.org. Fix anything it reports, then deliberately delete a closing tag and run it again to see how the error is described.',
      '[{"question":"What does a browser do with invalid HTML?","options":["Shows an error page","Tries to render it anyway, which can cause confusing layout bugs","Refuses to load","Fixes it permanently in your file"],"correct_index":1},{"question":"What is validator.w3.org used for?","options":["Hosting your site","Checking your markup against the HTML spec and reporting errors","Compressing images","Testing page speed"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

end $$;
